import{j as s,D as t,c as n,b as l,a7 as a,h as o,w as e,f as d,I as r,aV as h}from"./chunks/framework.nDdLsWIL.js";const b=JSON.parse('{"title":"PPT Agent 2.0：从五阶段内容流水线到可复用交付链路","description":"结合一次真实的 Harness Engineering 分享案例，系统整理一套从需求澄清、逐页检索、页面策划、SVG 生成到 PPTX 导出的 PPT Agent 2.0 工作流。","frontmatter":{"title":"PPT Agent 2.0：从五阶段内容流水线到可复用交付链路","description":"结合一次真实的 Harness Engineering 分享案例，系统整理一套从需求澄清、逐页检索、页面策划、SVG 生成到 PPTX 导出的 PPT Agent 2.0 工作流。","date":"2026-03-31T00:00:00.000Z","tags":["AI","PPT","Agent","Workflow"]},"headers":[],"relativePath":"ppt-agent2.0.md","filePath":"ppt-agent2.0.md","lastUpdated":null}'),c={name:"ppt-agent2.0.md"};function u(P,i,E,g,B,k){const p=t("Mermaid");return l(),n("div",{"data-pagefind-body":!0},[i[1]||(i[1]=a('<h1 id="ppt-agent-2-0-从五阶段内容流水线到可复用交付链路" tabindex="-1">PPT Agent 2.0：从五阶段内容流水线到可复用交付链路 <a class="header-anchor" href="#ppt-agent-2-0-从五阶段内容流水线到可复用交付链路" aria-label="Permalink to &quot;PPT Agent 2.0：从五阶段内容流水线到可复用交付链路&quot;">​</a></h1><p>之前写过一篇 <a href="./ppt-agent.html">《如何构建一个 PPT Agent：从需求调研到 SVG 页面生成》</a>，当时重点是把 PPT 生产拆成五个阶段，让模型不要一上来就套模板。</p><p>那篇文章解决了一个很重要的问题：<strong>先有内容结构，再有视觉设计</strong>。</p><p>但如果真的把这套流程跑到交付，你会发现还差一截。因为真实的 PPT 任务不只是“把 SVG 生出来”就结束了，它还包括：</p><ul><li>需求要不要继续追问</li><li>页面标题什么时候冻结</li><li>多个阶段文档怎么避免互相漂移</li><li>SVG 怎么稳定导成 PPTX</li><li>导入后为什么会留白边</li><li>最后怎么补出演讲稿，而不是只有一堆设计稿</li></ul><p>所以我更愿意把这次升级后的版本叫做 <code>PPT Agent 2.0</code>。</p><p>它不再只是一个“五阶段生成流程”，而是一条更完整的内容生产和交付链路。</p><hr><h2 id="为什么需要-2-0" tabindex="-1">为什么需要 2.0 <a class="header-anchor" href="#为什么需要-2-0" aria-label="Permalink to &quot;为什么需要 2.0&quot;">​</a></h2><p>很多 AI PPT 的问题，表面上看是页面不够好看，实际上是前面的信息链路就断了。</p><p>常见症状一般有这几种：</p><ul><li>用户只给一个标题，系统就开始出 15 页大纲</li><li>大纲是段落，不是结构</li><li>搜资料只搜一次总资料，没有按页面补内容</li><li>页面策划和视觉生成混在一起</li><li>最后虽然有 SVG，但没有办法稳定装进 <code>.pptx</code></li></ul><p>如果把这些问题放到一起看，你会发现缺的不是一个更强的“设计模型”，而是一条更稳的生产流程。</p><p>这也是 <code>2.0</code> 的核心变化：</p><ol><li>不再只关注五个内容阶段，而是补齐前后的工程化环节。</li><li>不再只生成页面，而是把脚本、测试、导出和讲稿一起纳入交付。</li><li>不再只讲方法论，而是用一次真实案例把流程跑通。</li></ol><hr><h2 id="这次我拿什么案例来验证" tabindex="-1">这次我拿什么案例来验证 <a class="header-anchor" href="#这次我拿什么案例来验证" aria-label="Permalink to &quot;这次我拿什么案例来验证&quot;">​</a></h2><p>这次我用的是一场内部技术分享，主题是 <code>Harness Engineering</code>。</p><p>它很适合做 PPT Agent 的验证案例，因为这个主题有几个特点：</p><ul><li>不是产品宣传，而是认知升级型分享</li><li>听众是程序员，而且很多人已经在高频使用 <code>Codex / Claude Code</code></li><li>内容不能停留在工具介绍，必须讲清楚判断</li><li>既要讲 OpenAI / Anthropic 的案例，也要回到团队自己的工程实践</li></ul><p>换句话说，这不是一个“搜几篇文章拼一拼”就能做好的 PPT。</p><p>它要求整条链路同时具备：</p><ul><li>结构能力</li><li>检索能力</li><li>策划能力</li><li>视觉生成能力</li><li>工程交付能力</li></ul><hr><h2 id="从-5-个阶段-升级成-7-个阶段" tabindex="-1">从 5 个阶段，升级成 7 个阶段 <a class="header-anchor" href="#从-5-个阶段-升级成-7-个阶段" aria-label="Permalink to &quot;从 5 个阶段，升级成 7 个阶段&quot;">​</a></h2><p>在 2.0 里，我建议把整条链路理解成 <code>7</code> 个阶段，而不是只盯着原来的五步。</p>',26)),(l(),o(h,null,{default:e(()=>[r(p,{id:"mermaid-182",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E9%98%B6%E6%AE%B5%200%3Cbr%2F%3E%E5%BB%BA%E7%AB%8B%E4%BB%BB%E5%8A%A1%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%20--%3E%20B%5B%22%E9%98%B6%E6%AE%B5%201%3Cbr%2F%3E%E9%9C%80%E6%B1%82%E8%B0%83%E7%A0%94%E4%B8%8E%E4%BB%BB%E5%8A%A1%E6%BE%84%E6%B8%85%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E9%98%B6%E6%AE%B5%202%3Cbr%2F%3E%E7%94%9F%E6%88%90%E7%BB%93%E6%9E%84%E5%8C%96%E5%A4%A7%E7%BA%B2%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E9%98%B6%E6%AE%B5%203%3Cbr%2F%3E%E6%8C%89%E9%A1%B5%E9%9D%A2%E4%B8%BB%E9%A2%98%E6%A3%80%E7%B4%A2%E8%B5%84%E6%96%99%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E9%98%B6%E6%AE%B5%204%3Cbr%2F%3E%E7%94%9F%E6%88%90%E9%A1%B5%E9%9D%A2%E7%AD%96%E5%88%92%E7%A8%BF%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E9%98%B6%E6%AE%B5%205%3Cbr%2F%3E%E6%8C%89%E5%B8%83%E5%B1%80%E8%A7%84%E5%88%99%E7%94%9F%E6%88%90%20SVG%20%E9%A1%B5%E9%9D%A2%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E9%98%B6%E6%AE%B5%206%3Cbr%2F%3E%E6%89%93%E5%8C%85%E4%B8%BA%20PPTX%20%E5%B9%B6%E9%AA%8C%E8%AF%81%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%E9%98%B6%E6%AE%B5%207%3Cbr%2F%3E%E6%BC%94%E8%AE%B2%E7%A8%BF%E4%B8%8E%E4%BA%A4%E4%BB%98%E6%95%B4%E7%90%86%22%5D%0A"})]),fallback:e(()=>i[0]||(i[0]=[d(" Loading... ")])),_:1})),i[2]||(i[2]=a(`<p>前五步负责内容和页面，后两步负责交付和复用。</p><p>如果只做到阶段五，你得到的是“设计产物”。</p><p>如果做到阶段七，你得到的才是一套可真正复用的 PPT 工作流。</p><hr><h2 id="阶段-0-先收拢上下文-而不是马上动手" tabindex="-1">阶段 0：先收拢上下文，而不是马上动手 <a class="header-anchor" href="#阶段-0-先收拢上下文-而不是马上动手" aria-label="Permalink to &quot;阶段 0：先收拢上下文，而不是马上动手&quot;">​</a></h2><p>很多任务一开始就失败，不是模型不够强，而是上下文不完整。</p><p>所以 2.0 里我加了一个显式的 <code>阶段 0</code>：先看当前目录有什么。</p><p>这一步通常要确认：</p><ul><li>当前目录有没有已有资料</li><li>是否允许联网检索</li><li>输出是只要 SVG，还是最终还要 <code>.pptx</code></li><li>有没有现成的图片、评审文档、实践文档</li><li>有没有仓库约束，比如命名、目录、构建要求</li></ul><p>这次 <code>Harness Engineering</code> 的案例里，目录下其实已经有很多基础资料，包括：</p><ul><li>阶段 1 到阶段 4 的文档</li><li>多篇本地技术资料</li><li><code>AIAPP</code> 实践说明</li><li>最终 SVG 产物</li></ul><p>如果跳过这一步，后面就很容易重复搜索，或者把已有材料浪费掉。</p><hr><h2 id="阶段-1-ppt-的起点不是版式-而是信息目标" tabindex="-1">阶段 1：PPT 的起点不是版式，而是信息目标 <a class="header-anchor" href="#阶段-1-ppt-的起点不是版式-而是信息目标" aria-label="Permalink to &quot;阶段 1：PPT 的起点不是版式，而是信息目标&quot;">​</a></h2><p>阶段 1 的核心不是“出内容”，而是把任务边界讲清楚。</p><p>这一步建议至少要问清楚：</p><ul><li>主题是什么</li><li>使用场景是什么</li><li>目标受众是谁</li><li>期望结果是什么</li><li>页数或时长大概多少</li></ul><p>以这次分享为例，最后澄清出来的结论不是“做一份 Harness Engineering 介绍”，而是：</p><blockquote><p>这是一场面向客户端开发组的认知升级型分享，主结论应落在：模型重要，但真正拉开差距的是 Harness。</p></blockquote><p>这一步听起来不“炫技”，但它决定了后面所有步骤的质量。</p><p>如果任务边界没定清楚，大纲一定会空。</p><hr><h2 id="阶段-2-大纲必须结构化-不能只是一段漂亮话" tabindex="-1">阶段 2：大纲必须结构化，不能只是一段漂亮话 <a class="header-anchor" href="#阶段-2-大纲必须结构化-不能只是一段漂亮话" aria-label="Permalink to &quot;阶段 2：大纲必须结构化，不能只是一段漂亮话&quot;">​</a></h2><p>PPT Agent 进入第二步之后，不应该马上写自然语言正文，而应该先产出结构化大纲。</p><p>我比较推荐强制输出 <code>JSON</code>，至少要包含：</p><ul><li>cover</li><li>table_of_contents</li><li>parts</li><li>end_page</li></ul><p>每一页都明确：</p><ul><li>标题是什么</li><li>这一页承载什么内容</li></ul><p>这样做的好处很直接：</p><ul><li>后续更容易做逐页检索</li><li>页面可以程序化编号</li><li>目录、章节、内容页之间的关系会非常清楚</li></ul><p>这次案例最后稳定下来的是 <code>17 页</code> 结构：</p><ul><li>第一部分：Harness 到底是什么</li><li>第二部分：OpenAI 的实践案例</li><li>第三部分：Anthropic 的实践案例</li><li>第四部分：从 AIAPP 试点到团队级 Harness</li></ul><p>这里的重点不是页数本身，而是它已经从“主题”变成了“页面列表”。</p><hr><h2 id="阶段-3-不是搜一遍总资料-而是逐页补内容" tabindex="-1">阶段 3：不是搜一遍总资料，而是逐页补内容 <a class="header-anchor" href="#阶段-3-不是搜一遍总资料-而是逐页补内容" aria-label="Permalink to &quot;阶段 3：不是搜一遍总资料，而是逐页补内容&quot;">​</a></h2><p>这是整个流程里最容易被偷懒，也最容易出问题的一步。</p><p>很多系统在做 PPT 时，会先搜一份总资料，然后让模型自己去“理解并分配”。这个做法看起来省事，实际上问题很大：</p><ul><li>有些页会被喂太多信息</li><li>有些页根本没有足够证据</li><li>不同页面会争抢同一份资料</li></ul><p>更稳的做法是：<strong>按页面粒度检索</strong>。</p><p>也就是说，大纲里每一页都应该拥有自己的资料块。</p><p>比如这次案例里：</p><ul><li><code>P3</code> 要解决的是“为什么现在行业集中开始讲 Harness”</li><li><code>P8</code> 要解决的是“为什么 OpenAI 放弃一个超长 AGENTS.md”</li><li><code>P12</code> 要解决的是“Anthropic 怎么做长时任务接力”</li><li><code>P14</code> 则完全依赖本地 <code>AIAPP</code> 实践文档</li></ul><p>你会发现，只有当资料按页组织后，后面的策划稿才会真正稳。</p><hr><h2 id="阶段-4-先做页面策划-再做视觉设计" tabindex="-1">阶段 4：先做页面策划，再做视觉设计 <a class="header-anchor" href="#阶段-4-先做页面策划-再做视觉设计" aria-label="Permalink to &quot;阶段 4：先做页面策划，再做视觉设计&quot;">​</a></h2><p>如果说前面三步在解决“讲什么”，那阶段 4 解决的是“这一页怎么讲”。</p><p>这一步本质上是把高端 PPT 里的“策划师”角色显式化。</p><p>每页策划稿建议固定输出这些字段：</p><ul><li>页面类型</li><li>核心观点</li><li>页面目标</li><li>内容模块划分</li><li>模块优先级</li><li>推荐版式</li><li>可用图片 / 图表 / 数字</li><li>演讲备注</li></ul><p>这样做的价值是：</p><ul><li>先把信息组织定住</li><li>再决定版式和视觉</li><li>避免模型一拿到内容就开始堆装饰</li></ul><p>这次实战里，阶段 4 其实帮我提前挡掉了不少问题。</p><p>比如：</p><ul><li><code>P9</code> 必须明确说 OpenAI 是重投入版本，借鉴的是原则，不是照搬做法</li><li><code>P13</code> 必须明确来源是 <code>Anthropic Labs</code> 的另一篇文章</li><li><code>P14</code> 不适合在页上放 commit hash，应该放结果面和代表性文件</li><li><code>P17</code> 不能写成结束语，必须给讨论留空间</li></ul><p>这些问题如果拖到 SVG 阶段才改，代价会高很多。</p><hr><h2 id="阶段-5-svg-不是模板输出-而是布局语言的执行结果" tabindex="-1">阶段 5：SVG 不是模板输出，而是布局语言的执行结果 <a class="header-anchor" href="#阶段-5-svg-不是模板输出-而是布局语言的执行结果" aria-label="Permalink to &quot;阶段 5：SVG 不是模板输出，而是布局语言的执行结果&quot;">​</a></h2><p>进入视觉生成后，真正要做的不是“随机生成一页好看的图”，而是让模型按照明确布局语言去渲染页面。</p><p>这次我用的是 <code>SVG + Bento Grid</code> 方案，约束包括：</p><ul><li><code>viewBox=&quot;0 0 1280 720&quot;</code></li><li>页面之间用卡片形成层级</li><li>卡片之间至少 <code>20px</code> 间距</li><li>内容优先驱动布局，而不是反过来</li></ul><p>这一步我最后落成了两类产物：</p><ul><li>一套逐页的 SVG 页面</li><li>一个可重复执行的生成脚本</li></ul><p>更关键的是，我没有只生成文件，还补了测试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_generate_svg_pages.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate_svg_pages.py</span></span></code></pre></div><p>这意味着以后页面再改，不用靠肉眼数页数、看文件名、查标题是否对齐，直接跑测试就知道有没有退化。</p><p>这就是 2.0 和“做完就算了”的最大差别。</p><hr><h2 id="阶段-6-从-svg-到-pptx-才是-2-0-真正补上的那一截" tabindex="-1">阶段 6：从 SVG 到 PPTX，才是 2.0 真正补上的那一截 <a class="header-anchor" href="#阶段-6-从-svg-到-pptx-才是-2-0-真正补上的那一截" aria-label="Permalink to &quot;阶段 6：从 SVG 到 PPTX，才是 2.0 真正补上的那一截&quot;">​</a></h2><p>这是我这次最直观踩到的坑。</p><p>最开始我以为只要有了 <code>SVG</code>，装进 <code>.pptx</code> 应该是很顺手的一步，结果事实完全不是这样。</p><p>首先，<code>python-pptx</code> 不能直接把 SVG 当图片塞进去。</p><p>其次，就算先截图成图片，再装进 PPTX，也不一定靠谱。因为如果你直接拿浏览器去截图 <code>file:///xxx.svg</code>，浏览器通常会把它当成一个居中的图像文档，而不是整页画布，于是导入 PPT 后四周就会出现白边。</p><p>这次最后稳定下来的做法是：</p><ol><li>先把每个 SVG 包进一个 <code>0 margin</code> 的临时 HTML</li><li>强制 SVG 以 <code>1280 x 720</code> 撑满视口</li><li>再用无头浏览器截图成 PNG</li><li>最后用 <code>python-pptx</code> 全屏铺到 slide</li></ol><p>对应的工程产物是：</p><ul><li><code>build_output_pptx.py</code></li><li><code>tests/test_build_output_pptx.py</code></li></ul><p>这一步很重要，因为它说明了一件事：</p><blockquote><p>如果没有打包和验证阶段，所谓的“PPT Agent”很多时候只是一套页面生成器，还不是一套真正的交付系统。</p></blockquote><hr><h2 id="阶段-7-最后别忘了演讲稿" tabindex="-1">阶段 7：最后别忘了演讲稿 <a class="header-anchor" href="#阶段-7-最后别忘了演讲稿" aria-label="Permalink to &quot;阶段 7：最后别忘了演讲稿&quot;">​</a></h2><p>到了这一步，很多系统会停下，因为“页面都出了”。</p><p>但真实的分享并不是只有页面，最后还要有人去讲。</p><p>所以 2.0 里我把“演讲稿”单独列成一个阶段。它至少要解决三件事：</p><ul><li>每页到底怎么讲</li><li>哪几页可以压缩</li><li>哪几页适合展开讨论</li></ul><p>这次最后形成的是一份逐页自然口语稿，而不是照本宣科式稿子。</p><p>它的价值不只是“方便演讲”，更重要的是你会倒逼自己再检查一遍：</p><ul><li>页面之间的转场顺不顺</li><li>逻辑有没有跳</li><li>讨论页的问题是不是够真实</li><li>有没有哪一页只是页面好看，但其实讲不出来</li></ul><p>很多 PPT 的问题，只有在写讲稿时才会暴露。</p><hr><h2 id="做完这一轮-我觉得-2-0-最值得保留的不是页面-而是这些中间资产" tabindex="-1">做完这一轮，我觉得 2.0 最值得保留的不是页面，而是这些中间资产 <a class="header-anchor" href="#做完这一轮-我觉得-2-0-最值得保留的不是页面-而是这些中间资产" aria-label="Permalink to &quot;做完这一轮，我觉得 2.0 最值得保留的不是页面，而是这些中间资产&quot;">​</a></h2><p>这次真正留下来的高价值资产，其实不是那 17 页 SVG，而是下面这些：</p><ul><li>阶段 1 到阶段 4 的文档</li><li>SVG 生成脚本</li><li>PPTX 打包脚本</li><li>两组测试</li><li>演讲稿</li><li>最后抽象出来的 SOP</li></ul><p>如果没有这些东西，下一次做新主题 PPT 时，你还是会从零开始。</p><p>如果这些都留下来，下次你只需要替换：</p><ul><li>主题</li><li>资料</li><li>页面清单</li><li>页面内容数据</li></ul><p>整条链路就可以复用。</p><p>这也是为什么我会把这套东西叫做 <code>PPT Agent 2.0</code>，而不是“PPT 生成器升级版”。</p><p>它已经不只是一个模型提示词，而是一条完整的内容生产和交付工作流。</p><hr><h2 id="这套流程还可以继续优化什么" tabindex="-1">这套流程还可以继续优化什么 <a class="header-anchor" href="#这套流程还可以继续优化什么" aria-label="Permalink to &quot;这套流程还可以继续优化什么&quot;">​</a></h2><p>虽然 2.0 已经能跑通，但它还不是终点。</p><p>我觉得下一步最值得优化的有三件事：</p><h3 id="_1-增加一个-内容冻结-关口" tabindex="-1">1. 增加一个“内容冻结”关口 <a class="header-anchor" href="#_1-增加一个-内容冻结-关口" aria-label="Permalink to &quot;1. 增加一个“内容冻结”关口&quot;">​</a></h3><p>在阶段 4 到阶段 5 之间，强制冻结：</p><ul><li>页面标题</li><li>核心观点</li><li>页码</li><li>讨论问题</li><li>文件名映射</li></ul><p>不冻结，就不要进 SVG。</p><h3 id="_2-建一个唯一的页面清单" tabindex="-1">2. 建一个唯一的页面清单 <a class="header-anchor" href="#_2-建一个唯一的页面清单" aria-label="Permalink to &quot;2. 建一个唯一的页面清单&quot;">​</a></h3><p>现在信息还散在：</p><ul><li>大纲</li><li>逐页资料</li><li>策划稿</li><li>SVG 页面</li></ul><p>更稳的做法是维护一个 <code>page-manifest.json</code>，作为后面所有阶段的唯一页面索引。</p><h3 id="_3-提前决定最终交付是-图片型-ppt-还是-可编辑-ppt" tabindex="-1">3. 提前决定最终交付是“图片型 PPT”还是“可编辑 PPT” <a class="header-anchor" href="#_3-提前决定最终交付是-图片型-ppt-还是-可编辑-ppt" aria-label="Permalink to &quot;3. 提前决定最终交付是“图片型 PPT”还是“可编辑 PPT”&quot;">​</a></h3><p>这次的 <code>.pptx</code> 是图片型 PPT，优点是稳定，缺点是后续不好在 PowerPoint 里细改。</p><p>这个决策应该前置，而不是到最后才发现。</p><hr><h2 id="一套最小可复用实现" tabindex="-1">一套最小可复用实现 <a class="header-anchor" href="#一套最小可复用实现" aria-label="Permalink to &quot;一套最小可复用实现&quot;">​</a></h2><p>如果你现在就想做一个最小可用版本，我建议先不要上太重的系统，保留下面这些就够了：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>├── 阶段1：需求调研与任务澄清</span></span>
<span class="line"><span>├── 阶段2：结构化大纲</span></span>
<span class="line"><span>├── 阶段3：逐页资料检索</span></span>
<span class="line"><span>├── 阶段4：页面策划稿</span></span>
<span class="line"><span></span></span>
<span class="line"><span>scripts/</span></span>
<span class="line"><span>├── generate_svg_pages.py</span></span>
<span class="line"><span>└── build_output_pptx.py</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tests/</span></span>
<span class="line"><span>├── test_generate_svg_pages.py</span></span>
<span class="line"><span>└── test_build_output_pptx.py</span></span></code></pre></div><p>最小命令链路也很简单：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_generate_svg_pages.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate_svg_pages.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_build_output_pptx.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_output_pptx.py</span></span></code></pre></div><p>把这条链路先跑通，比一开始追求“全自动、高智能、多模板”更重要。</p><hr><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>我现在越来越觉得，做 PPT Agent 和做别的 Agent 系统其实是同一件事：</p><p>真正决定效果的，不是最后那一下生成，而是前面的信息组织、约束设计、反馈回路和交付验证。</p><p>如果只看最后生成了一堆页面，那它还是一次性劳动。</p><p>如果把中间文档、脚本、测试、导出和讲稿都沉淀下来，这件事才真正从“会用模型”升级成了一套工程化工作流。</p><p>这也是 <code>PPT Agent 2.0</code> 想表达的核心：</p><blockquote><p>不是让模型替你做 PPT，而是把 PPT 生产过程拆成一条可以被 Agent 稳定接管的流水线。</p></blockquote>`,128))])}const _=s(c,[["render",u]]);export{b as __pageData,_ as default};
